    const by = new Map<number, PctOn>();
    for (const p of this.people()) by.set(p.id, (date) => pctOn(this.ratesOf(gradeOn(p, date)), date));
    return by;
  });
  /** Each grade's rate in force on the sheet's today, for the grades that have one. */
